  /** @type {{ get(id: string): ResolvedColumn|undefined, visible(): ResolvedColumn[] }} */
  #columns;

  /** @type {{ byKey(key: string): Row|undefined, at(index: number): Row|undefined, count(): number }} */
  #rows;

  /** @type {(type: string, payload?: Record<string, unknown>, origin?: string) => void} */
  #emit = () => {};

  /** @type {unknown} the grid handed to user callbacks */
